USE StoreSalesAnalysis;
GO
select * from CustomerBuyingBehaviour;
-- Revenue Analysis
-- compare total revenue generated by male and female customers.

select gender, sum(purchase_amount) as total_revenue
from CustomerBuyingBehaviour
group by gender;

-- Discount and spending Analysis
-- Identify discount users whose purchase ammounts were at or abovr the over average
select customer_id, purchase_amount from CustomerBuyingBehaviour
where discount_applied ='Yes'
and purchase_amount >=(select avg(purchase_amount) from CustomerBuyingBehaviour);

-- product rating analysis
-- Ranked the top 5 products by average review rating
SELECT TOP 5
    item_purchased,
    ROUND(AVG(CAST(review_rating AS DECIMAL(10,2))), 2) AS [Average Product Rating]
FROM CustomerBuyingBehaviour
GROUP BY item_purchased
ORDER BY AVG(CAST(review_rating AS DECIMAL(10,2))) DESC;

-- 4, Shipping Analysis
-- Compare average purchase amount for standard and expressshipping
select shipping_type, round(avg(purchase_amount),2)
from CustomerBuyingBehaviour
where shipping_type in ('Standard', 'Express')
group by shipping_type;

--5. Subscription Analysis--
-- compare customer counts, average spending, and total revenue between subscribers
-- and non-subscribers.
select subscription_status,
count(customer_id) as total_customers,
round(avg(purchase_amount),2) as avg_spend,
round(sum(purchase_amount),2) as total_revenue
from CustomerBuyingBehaviour
group by subscription_status
order by total_revenue, avg_spend desc;

--6. discount dependency analysis
-- identify the top 5 products by percentage of purchases with discount applied.
select top 5 item_purchased,
    round(
        100*sum(
            case when discount_applied = 'Yes' then 1
            else 0 end)/count(*),2)
            as discount_rate
            from CustomerBuyingBehaviour
            group by item_purchased
            order by discount_rate desc;
           --- limit 5; not applicable in ms sql
           -- desc means decending order


 -- 7. Customer segmentation
-- Classified customers into New, Returning and Loyal based on previous purchases
-- previous_purchases = 1       -> New
-- previous_purchases 2 to 10   -> Returning
-- previous_purchases > 10      -> Loyal
WITH customer_type AS (
    SELECT
        customer_id,
        previous_purchases,
        CASE
            WHEN previous_purchases = 1 THEN 'New'
            WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
            ELSE 'Loyal'
        END AS customer_segment
    FROM CustomerBuyingBehaviour
)
SELECT
    customer_segment,
    COUNT(*) AS [Number of Customers] 
FROM customer_type
GROUP BY customer_segment
ORDER BY [Number of Customers] DESC;

--product popularity analysis
-- identify the top 3 most purchased products within each category.
with item_counts as
    (select category, item_purchased,
    count(customer_id) as total_orders,
    row_number()over(partition by category order by count(customer_id)desc) as item_rank
    from CustomerBuyingBehaviour
    group by category, item_purchased)
    select item_rank, category, item_purchased, total_orders
    from item_counts
    where item_rank <=3;

    --9. Repeat buyers analysis
    -- compare subscription status among customerss with more than 5 previous purchases.
    select subscription_status,
    count(customer_id) as repeated_buyers
    from CustomerBuyingBehaviour
    where previous_purchases >5
    group by subscription_status;

    -- 10. Age group Revenue Analysis
    -- compare total revenue across customer age group
    select age_group, sum(purchase_amount) as total_revenue
    from CustomerBuyingBehaviour
    group by age_group
    order by total_revenue desc;


    SELECT @@SERVERNAME;
